function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.fillStyle = 'pink';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50 + 10 * Math.sin(t), 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 - 60);
  ctx.lineTo(W/2, H/2 - 30);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 30, H/2 - 45);
  ctx.lineTo(W/2 - 10, H/2 - 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + 30, H/2 - 45);
  ctx.lineTo(W/2 + 10, H/2 - 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50 + 10 * Math.sin(t));
  ctx.stroke();
  ctx.fillStyle = 'red';
  ctx.beginPath();
  ctx.arc(W/2 - 40, H/2 - 20, 5 + 2 * Math.sin(t), 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.arc(W/2 + 40, H/2 - 20, 5 + 2 * Math.sin(t), 0, 2 * Math.PI);
  ctx.fill();
  ctx.restore();
}
